<?php
namespace MarinePortal\Email;
use PHPMailer\PHPMailer\PHPMailer;
class SmtpDriver implements EmailInterface { public function __construct(private array $cfg, private string $from, private string $replyTo=''){} public function send(string $to, string $subject, string $html, ?string $text=null, array $opts=[]): bool { $m=new PHPMailer(true); try{ $m->isSMTP(); $m->Host=$this->cfg['host']; $m->Port=(int)($this->cfg['port']??587); $m->SMTPAuth=!empty($this->cfg['username']); if($m->SMTPAuth){ $m->Username=$this->cfg['username']; $m->Password=$this->cfg['password']; } $m->SMTPSecure=$this->cfg['encryption']??'tls'; $m->setFrom($this->parseEmail($this->from),$this->parseName($this->from)); $m->addAddress($to); $m->isHTML(true); $m->Subject=$subject; $m->Body=$html; return $m->send(); }catch(\Throwable $e){ error_log($e->getMessage()); return false; } } private function parseEmail($f){ if(preg_match('/<(.*?)>/',$f,$m)) return $m[1]; return $f; } private function parseName($f){ if(preg_match('/^(.*?)\s*</',$f,$m)) return trim($m[1],' "'); return ''; } }
